<script setup>
import { ref, onMounted } from 'vue'
import ProofThumb from '../../h5/src/ProofThumb.vue'
import { categoryOptions, categoryName } from '../../shared/categories.js'
const token=ref(localStorage.getItem('cym-admin-token')||''), tab=ref('overview'), menu=ref(false), login=ref({username:'',password:''}), users=ref([]),products=ref([]),orders=ref([]),overview=ref({}), message=ref(''), edit=ref(null)
const orderSearch=ref(''), userSearch=ref(''), ledger=ref(null)
const newUser=ref(null), creatingUser=ref(false)
const withdrawalList=ref([]), withdrawalBusy=ref(false)
const uploading=ref(false)
const blank=()=>({name:'',category:'',description:'',image:'',cost:'0',reward:'0',stock:0,active:true,options:[],detail_images:[]})
async function api(path,opts={}) { const response=await fetch('/api'+path,{...opts,headers:{'Content-Type':'application/json',...(token.value?{Authorization:`Bearer ${token.value}`}:{})},body:opts.body?JSON.stringify(opts.body):undefined});const data=await response.json();if(!response.ok)throw new Error(data.message||'操作失败');return data.data??data }
function notice(e){message.value=e?.message||e;setTimeout(()=>message.value='',3000)}
async function refresh(){try{[overview.value,users.value,products.value,orders.value]=await Promise.all(['/admin/overview','/admin/users?q='+encodeURIComponent(userSearch.value.trim()),'/admin/products','/admin/orders?q='+encodeURIComponent(orderSearch.value.trim())].map(api));if(tab.value==='withdrawals')withdrawalList.value=await api('/admin/withdrawals')}catch(e){notice(e)}}
async function showWithdrawalAccount(item){try{item.account=await api('/admin/withdrawals/'+item.id)}catch(e){notice(e)}}
async function reviewWithdrawal(item,action){if(withdrawalBusy.value)return;let reason='',transfer_note='';if(action==='reject'){reason=prompt('请输入驳回原因')?.trim();if(!reason)return}else if(action==='paid'){if(!item.has_proof){notice('请先上传转账截图');return}transfer_note=prompt('请输入支付宝转账记录或流水号')?.trim();if(!transfer_note)return;if(!confirm('确认已完成支付宝线下转账？'))return}else if(!confirm('确认审核通过？请在线下转账后上传截图并标记已转账。'))return;withdrawalBusy.value=true;try{await api('/admin/withdrawals/'+item.id+'/'+action,{method:'POST',body:{reason,transfer_note}});notice(action==='reject'?'已驳回并退回产品券':action==='approve'?'审核通过，请线下转账':'已标记转账完成');await refresh()}catch(e){notice(e)}finally{withdrawalBusy.value=false}}
async function uploadWithdrawalProof(item,event){const file=event.target.files?.[0];event.target.value='';if(!file||withdrawalBusy.value)return;if(file.size>5*1024*1024){notice('截图不能超过 5MB');return}withdrawalBusy.value=true;try{const response=await fetch('/api/admin/withdrawals/'+item.id+'/proof',{method:'POST',headers:{Authorization:`Bearer ${token.value}`,'Content-Type':file.type},body:file});const data=await response.json();if(!response.ok)throw new Error(data.message||'截图上传失败');item.has_proof=1;item.proofVersion=(item.proofVersion||0)+1;notice('截图已上传，请核对后填写转账记录并确认')}catch(e){notice(e)}finally{withdrawalBusy.value=false}}
async function showLedger(user){try{ledger.value={user,entries:await api('/admin/users/'+user.id+'/transactions')}}catch(e){notice(e)}}
async function createUser(){if(creatingUser.value)return;creatingUser.value=true;try{await api('/admin/users',{method:'POST',body:newUser.value});newUser.value=null;userSearch.value='';notice('用户已创建');await refresh()}catch(e){notice(e)}finally{creatingUser.value=false}}
function addressText(order){try { const a=typeof order.address==='string'?JSON.parse(order.address):order.address; return [a.contact_name,a.contact_phone,a.province,a.city,a.district,a.detail].filter(Boolean).join(' ') } catch { return '' }}
async function signIn(){try{const result=await api('/admin/login',{method:'POST',body:login.value});token.value=result.token;localStorage.setItem('cym-admin-token',result.token);await refresh()}catch(e){notice(e)}}
function signOut(){token.value='';withdrawalList.value=[];localStorage.removeItem('cym-admin-token')}
function go(value){tab.value=value;menu.value=false;if(value==='withdrawals')refresh();else withdrawalList.value=[]}
async function save(){if(uploading.value)return;try{const options=edit.value.options.map(o=>({...o,label:o.label.trim()}));if(options.some(o=>!o.label))throw new Error('请填写款式名称或删除空款式');const body={...edit.value,options};await api('/admin/products'+(edit.value.id?'/'+edit.value.id:''),{method:edit.value.id?'PUT':'POST',body});edit.value=null;notice('商品已保存');await refresh()}catch(e){notice(e)}}
async function uploadImages(event,cover=false){const form=edit.value, files=Array.from(event.target.files||[]);event.target.value='';if(!files.length||!form)return;if(!cover && form.detail_images.length+files.length>9){notice('详情图片最多上传 9 张');return}uploading.value=true;try{for(const file of files){if(file.size>5*1024*1024)throw new Error('每张图片不能超过 5MB');const response=await fetch('/api/admin/uploads',{method:'POST',headers:{'Content-Type':file.type,Authorization:`Bearer ${token.value}`},body:file});const data=await response.json();if(!response.ok)throw new Error(data.message||'图片上传失败');if(edit.value!==form)return;if(cover)form.image=data.data.url;else form.detail_images.push(data.data.url)}notice('图片上传成功')}catch(e){notice(e)}finally{uploading.value=false}}
function addOption(){edit.value.options.push({id:crypto.randomUUID(),label:''})}
async function topup(user){const amount=window.prompt(`为 ${user.username} 充值产品券数量`);if(!amount)return;try{await api('/admin/users/'+user.id+'/topup',{method:'POST',body:{amount,request_id:crypto.randomUUID()}});notice('充值成功');await refresh()}catch(e){notice(e)}}
async function toggleUser(user){try{await api('/admin/users/'+user.id+'/status',{method:'PUT',body:{status:user.status==='active'?'disabled':'active'}});notice('用户状态已更新');await refresh()}catch(e){notice(e)}}
async function arrival(order){const pickup_code=window.prompt('输入提货码',order.pickup_code||'');if(!pickup_code)return;const message=window.prompt('到货留言（可选）',order.pickup_message||'');try{await api('/admin/orders/'+order.id+'/notice',{method:'PUT',body:{pickup_code,message:message||''}});notice('通知已保存');await refresh()}catch(e){notice(e)}}
function parseList(value){try{const list=typeof value==='string'?JSON.parse(value):value;return Array.isArray(list)?list:[]}catch{return []}}
function modify(p){edit.value={...p,category:p.category ? categoryName(p.category) : '',options:parseList(p.options).map(o=>({...o})),detail_images:[...parseList(p.detail_images)]}}
onMounted(()=>{if(token.value)refresh()})
</script>
<template><div v-if="message" class="toast">{{ message }}</div><div v-if="!token" class="login"><section><div class="brand-mark">商</div><h1>商圈管理后台</h1><p>欢迎回来，请登录您的账号</p><input v-model="login.username" placeholder="管理员账号"><input v-model="login.password" type="password" placeholder="密码" @keyup.enter="signIn"><button class="primary" @click="signIn">登录后台</button></section></div><div v-else class="layout"><aside :class="{open:menu}"><div class="brand"><span>商</span><div><b>本地商圈</b><small>运营管理平台</small></div><button class="menu-close" @click="menu=false">×</button></div><nav><button :class="{active:tab==='overview'}" @click="go('overview')">◫　运营概览</button><button :class="{active:tab==='products'}" @click="go('products')">▣　商品管理</button><button :class="{active:tab==='users'}" @click="go('users')">♧　用户管理</button><button :class="{active:tab==='orders'}" @click="go('orders')">▤　订单管理</button><button :class="{active:tab==='withdrawals'}" @click="go('withdrawals')">¥　提现管理</button></nav><button class="logout" @click="signOut">退出登录</button></aside><div v-if="menu" class="shade" @click="menu=false"></div><div class="content"><header><button class="menu" @click="menu=true">☰</button><div><b>商圈运营中心</b><small>让每一次经营更简单</small></div><button class="refresh" @click="refresh">↻ 刷新数据</button></header><main><section class="intro"><div><small>LOCAL COMMERCE</small><h1>{{ {overview:'运营概览',products:'商品管理',users:'用户管理',orders:'订单管理',withdrawals:'提现管理'}[tab] }}</h1><p>本地商圈 · 运营管理平台</p></div><button v-if="tab==='products'" class="primary" @click="edit=blank()">＋ 添加商品</button><button v-if="tab==='users'" class="primary" @click="newUser={phone:'',username:'',password:'',parent_phone:'',balance:'0'}">＋ 添加用户</button></section>
<template v-if="tab==='overview'"><div class="metrics"><article><span>成交订单</span><strong>{{ overview.order_count || 0 }}</strong><small>累计订单</small></article><article><span>产品券消耗</span><strong>{{ overview.total_cost || '0.00' }}</strong><small>累计消耗</small></article><article><span>商圈收益</span><strong>{{ overview.total_reward || '0.00' }}</strong><small>累计发放</small></article><article><span>商圈用户</span><strong>{{ overview.user_count || 0 }}</strong><small>用户总数</small></article></div><section class="panel"><h2>近 30 天成交趋势</h2><div v-for="row in overview.trend" :key="row.day" class="row"><b>{{ row.day }}</b><span>{{ row.order_count }} 笔 · {{ row.total_cost }} 券</span></div><p v-if="!overview.trend?.length" class="empty">暂无成交记录</p></section><section class="panel"><h2>商品成交排行</h2><div v-for="p in overview.products" :key="p.product_id" class="row"><b>{{ p.product_name }}</b><span>{{ p.order_count }} 笔 · {{ p.total_cost }} 券</span></div><p v-if="!overview.products?.length" class="empty">暂无成交记录</p></section></template>
<template v-if="tab==='users'"><section class="panel"><h2>用户列表 <small>最多显示 500 人</small></h2><form @submit.prevent="refresh"><input v-model="userSearch" placeholder="搜索用户名、手机号或 ID"><button class="outline">搜索</button></form><div v-for="u in users" :key="u.id" class="item"><div class="item-main"><b>{{ u.username }}</b><small>{{ u.phone }} · ID {{ u.id }} · {{ u.status==='active'?'正常':'已停用' }} <span v-if="u.is_root">· 根账户</span></small></div><div><span>余额</span><b>{{ u.balance }} 券</b></div><div><span>复购</span><b>{{ u.purchase_count }} 次</b></div><div><button class="outline" @click="showLedger(u)">流水</button><button class="outline" @click="topup(u)">充值</button><button v-if="!u.is_root" class="outline" @click="toggleUser(u)">{{ u.status==='active'?'停用':'启用' }}</button></div></div><p v-if="!users.length" class="empty">暂无用户</p></section></template>
<template v-if="tab==='products'"><section class="panel"><h2>商圈商品 <small>{{ products.length }} 件</small></h2><div v-for="p in products" :key="p.id" class="item"><div class="item-main"><b>{{ p.name }}</b><small>{{ categoryName(p.category) }} · {{ p.active?'已上架':'已下架' }} · 库存 {{ p.stock }}</small></div><div><span>消耗</span><b>{{ p.cost }} 券</b></div><div><span>收益</span><b>{{ p.reward }} 券</b></div><button class="outline" @click="modify(p)">编辑</button></div><p v-if="!products.length" class="empty">暂无商品，请添加</p></section></template>
<template v-if="tab==='withdrawals'"><section class="panel"><h2>提现申请 <small>待处理优先</small></h2><div v-for="w in withdrawalList" :key="w.id" class="order"><div class="row"><div><b>{{ w.username }} · {{ w.phone }}</b><small>申请 #{{ w.id }} · {{ w.created_at }}</small></div><b>{{ {pending:'待审核',approved:'待线下转账',paid:'已转账',rejected:'已驳回'}[w.status] }}</b></div><p>申请 {{ w.amount }} 产品券 · 手续费 {{ w.fee }} · 应转账 {{ w.net }} 元</p><p>支付宝账号：{{ w.account_number }}</p><button class="outline" @click="showWithdrawalAccount(w)">查看收款信息</button><p v-if="w.account">收款人：{{ w.account.account_name }} · 支付宝账号：{{ w.account.account_number }}</p><p v-if="w.reason">驳回原因：{{ w.reason }}</p><button v-if="w.status==='pending'" class="outline" :disabled="withdrawalBusy" @click="reviewWithdrawal(w,'approve')">审核通过</button><label v-if="w.status==='approved'">{{ w.has_proof ? '更换转账截图' : '上传转账截图' }}<input type="file" accept="image/jpeg,image/png,image/webp" :disabled="withdrawalBusy" @change="uploadWithdrawalProof(w,$event)"></label><ProofThumb v-if="w.has_proof" :key="w.id+'-'+(w.proofVersion||0)" :id="w.id" :token="token" /><p v-if="w.transfer_note">转账记录：{{ w.transfer_note }}</p><button v-if="w.status==='approved'" class="outline" :disabled="withdrawalBusy || !w.has_proof" @click="reviewWithdrawal(w,'paid')">已线下转账</button><button v-if="w.status==='pending'" class="outline" :disabled="withdrawalBusy" @click="reviewWithdrawal(w,'reject')">驳回并退券</button></div><p v-if="!withdrawalList.length" class="empty">暂无提现申请</p></section></template>
<template v-if="tab==='orders'"><section class="panel"><h2>商圈订单 <small>最多显示 500 笔</small></h2><form @submit.prevent="refresh"><input v-model="orderSearch" placeholder="订单号、商品、用户名或手机号"><button class="outline">搜索</button></form><div v-for="o in orders" :key="o.id" class="order"><div class="row"><div><b>{{ o.product_name }}</b><small>{{ o.order_no }} · {{ o.username }} {{ o.phone }}</small></div><b>{{ o.cost }} 券</b></div><div class="order-facts"><span>第 {{ o.purchase_sequence }} 次购买</span><span>收益 {{ o.reward }} 券</span><span>收益去向 {{ o.reward_destination==='root'?'根账户':o.recipient_name }}</span><span>{{ o.received_at ? '用户已收货' : (o.pickup_code ? '等待用户收货' : '未发送到货通知') }}</span></div><p v-if="o.variant">款式：{{ o.variant }}</p><p>收货地址：{{ addressText(o) }}</p><p v-if="o.pickup_code">提货码：{{ o.pickup_code }} {{ o.pickup_message }}</p><button class="outline" @click="arrival(o)">{{ o.pickup_code ? '重新发送到货通知' : '发送到货通知' }}</button></div><p v-if="!orders.length" class="empty">暂无订单</p></section></template>
</main></div><div v-if="newUser" class="overlay" @click.self="newUser=null"><section class="dialog"><header><h2>添加用户</h2><button @click="newUser=null">×</button></header><form class="form" @submit.prevent="createUser"><label>手机号<input v-model.trim="newUser.phone" type="tel" maxlength="11" required></label><label>用户名<input v-model.trim="newUser.username" maxlength="20" required></label><label>登录密码<input v-model="newUser.password" type="password" minlength="6" maxlength="64" required></label><label>上级手机号（选填）<input v-model.trim="newUser.parent_phone" type="tel" maxlength="11" placeholder="不填写表示没有上级"></label><label>初始产品券<input v-model="newUser.balance" type="number" min="0" step="0.01" required></label><button class="primary" :disabled="creatingUser">{{ creatingUser ? '创建中…' : '创建用户' }}</button></form></section></div><div v-if="ledger" class="overlay" @click.self="ledger=null"><section class="dialog"><header><h2>{{ ledger.user.username }} 的产品券流水</h2><button @click="ledger=null">×</button></header><div v-for="entry in ledger.entries" :key="entry.id" class="row"><div><b>{{ entry.description }}</b><small>{{ entry.created_at }}</small></div><b>{{ entry.amount }} 券</b></div><p v-if="!ledger.entries.length" class="empty">暂无流水</p></section></div><div v-if="edit" class="overlay" @click.self="edit=null"><section class="dialog"><header><h2>{{ edit.id?'编辑商品':'添加商品' }}</h2><button @click="edit=null">×</button></header><div class="form"><label>商品名称<input v-model="edit.name"></label><label>商品分类<input v-model.trim="edit.category" list="product-categories" maxlength="40" placeholder="输入或选择分类，留空为未分类"><datalist id="product-categories"><option v-for="category in categoryOptions(products)" :key="category" :value="category"></option></datalist></label><label>商品描述<textarea v-model="edit.description"></textarea></label><div class="image-field"><span>商品封面</span><input type="file" accept="image/jpeg,image/png,image/webp,image/gif" :disabled="uploading" @change="uploadImages($event,true)"><div v-if="edit.image" class="image-preview"><img :src="edit.image" alt="商品封面"><button type="button" class="outline" @click="edit.image=''">移除封面</button></div></div><div class="form-grid"><label>消耗产品券<input v-model="edit.cost" type="number" step="0.01"></label><label>收益产品券<input v-model="edit.reward" type="number" step="0.01"></label><label>库存<input v-model="edit.stock" type="number"></label></div><div class="option-field"><span>商品款式（可选）</span><div v-for="(option,index) in edit.options" :key="option.id" class="option-row"><input v-model="option.label" maxlength="100" placeholder="例如：红色 / 大号"><button type="button" class="outline" @click="edit.options.splice(index,1)">删除</button></div><button type="button" class="outline" @click="addOption">＋ 添加款式</button></div><div class="image-field"><span>商品详情图片（最多 9 张，每张不超过 5MB）</span><input type="file" accept="image/jpeg,image/png,image/webp,image/gif" multiple :disabled="uploading" @change="uploadImages($event)"><div v-for="(url,index) in edit.detail_images" :key="index" class="image-preview"><img :src="url" :alt="`详情图片 ${index+1}`"><button type="button" class="outline" @click="edit.detail_images.splice(index,1)">删除</button></div></div><label><input v-model="edit.active" type="checkbox"> 上架</label><button class="primary" :disabled="uploading" @click="save">{{ uploading ? '图片上传中…' : '保存商品' }}</button></div></section></div></div></template>
